# The memory channel, both ends of it. PROPOSED is what this attempt wrote; DELIVERED is the
# read-only copy of what the previous attempt's verifier persisted. The canonical state itself is
# harness-private and is named only so the isolation check can say what must not be written.
PROPOSED_CARRY = os.path.join(BUNDLE, 'carry/notes.json')
PROPOSED_CARRY_ARG = 'carry/notes.json'
DELIVERED_CARRY = os.path.join(BUNDLE, 'carry/delivered_notes.json')
