@check(id="bar_gated_wallclock_ramp_over_the_scored_attempt", weight=10, knockout=True, kind="outcome")
def test_bar_gated_wallclock_ramp_over_the_scored_attempt():
    # require_measured FIRST, before anything is read. Reading the record before saying the slot
    # is not yet measurable lets a missing-file error mask the unmeasured signal, and the verifier
    # then reports gradeable=true with r_det=0.0 -- which asserts the agent scored zero where the
    # honest claim is that the slot cannot yet be scored at all.
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    seconds = measure(c["floor"])
    s = ramp(seconds, c["floor"], c["knee"])
    return seconds <= c["dichotomizing_threshold"], evidence(
        mean_gated_seconds=seconds, s_outcome=s, floor_seconds=c["floor"],
        knee_seconds=c["knee"], configurations=len(graded_blocks()))


@check(id="carry_entries_carry_the_six_named_scalars_and_nothing_else", weight=5, knockout=True, kind="carry_store")
def test_carry_entries_carry_the_six_named_scalars_and_nothing_else():
    raw, doc, err = proposed_store()
    if raw is None:
        return True, evidence(target="proposed_carry_store", store_absent=True)
    if err is not None or not isinstance(doc, dict):
        return False, evidence(target="proposed_carry_store", error=err,
                               reason="carry_store_invalid")
    findings = []
    for config_id in sorted(str(k) for k in doc):
        entry = doc[config_id]
        if config_id not in CONFIG_ROSTER:
            findings.append({"config_id": config_id, "reason": "unknown_config_id"})
            continue
        if not isinstance(entry, dict):
            findings.append({"config_id": config_id, "reason": "entry_is_not_an_object"})
            continue
        keys = set(str(k) for k in entry)
        missing = [f for f in SCALAR_FIELDS if f not in keys]
        unknown = sorted(keys - set(SCALAR_FIELDS) - set([SRC_FIELD, TAG_FIELD]))
        if missing:
            findings.append({"config_id": config_id, "missing": missing,
                             "reason": "entry_missing_a_named_scalar"})
        if unknown:
            findings.append({"config_id": config_id, "unknown": unknown,
                             "reason": "unknown_key_in_a_closed_schema"})
        for field in SCALAR_FIELDS:
            if field not in entry:
                continue
            value = entry[field]
            if isinstance(value, (list, dict)):
                findings.append({"config_id": config_id, "field": field,
                                 "reason": "array_or_object_field"})
                continue
            got = numeric(value)
            if got is None:
                findings.append({"config_id": config_id, "field": field,
                                 "reason": "field_is_not_a_finite_scalar"})
                continue
            outside = out_of_domain(field, got)
            if outside:
                findings.append({"config_id": config_id, "field": field, "value": got,
                                 "reason": outside})
        if numeric(entry.get(SRC_FIELD)) not in (float(SRC_OBSERVED), float(SRC_PREDICTED)):
            findings.append({"config_id": config_id, "src": entry.get(SRC_FIELD),
                             "reason": "src_is_not_one_bit"})
        if TAG_FIELD in entry:
            tag = entry[TAG_FIELD]
            if not isinstance(tag, str) or len(tag.encode("utf-8")) > TAG_MAX_BYTES:
                findings.append({"config_id": config_id,
                                 "reason": "encoder_tag_is_not_a_short_string"})
    ok = not findings
    return ok, evidence(target="proposed_carry_store", schema_findings=findings,
                        scalar_fields=list(SCALAR_FIELDS), src_field=SRC_FIELD,
                        reason=None if ok else "carry_store_invalid")


@check(id="carry_lifecycle_validates_stamps_expires_persists_then_reports", weight=3, knockout=False, kind="carry_lifecycle")
def test_carry_lifecycle_validates_stamps_expires_persists_then_reports():
    record = attempt_record()
    trace = tuple(token(step) for step in as_list(record.get("carry_lifecycle_trace")))
    if not trace:
        return False, evidence(reason="carry_lifecycle_untraced")
    order_holds = trace == LIFECYCLE_ORDER
    attempt = attempt_index()
    incoming = record.get("incoming_store_stamps")
    reported = record.get("expired_identifiers")
    if attempt is None or not isinstance(incoming, dict) or not isinstance(reported, list):
        return False, evidence(trace=list(trace), order_holds=order_holds,
                               reason="expiry_report_unrecorded")
    recomputed = sorted(str(config_id) for config_id, stamp in incoming.items()
                        if numeric(stamp) is not None
                        and attempt - numeric(stamp) > CARRY_TTL_ATTEMPTS)
    reported_ids = sorted(str(c) for c in reported)
    ok = order_holds and reported_ids == recomputed
    return ok, evidence(trace=list(trace), bound_order=list(LIFECYCLE_ORDER),
                        order_holds=order_holds, reported_expired=reported_ids,
                        recomputed_expired=recomputed,
                        reason=None if ok else "carry_lifecycle_violation")


@check(id="carry_store_fits_the_two_kilobyte_channel", weight=5, knockout=True, kind="carry_store")
def test_carry_store_fits_the_two_kilobyte_channel():
    raw, doc, err = proposed_store()
    if raw is None:
        # An absent store is admissible: the first attempt has none, and NC-AMNESIC runs with
        # none deliberately. What is not admissible is a present one over the cap.
        return True, evidence(target="proposed_carry_store", store_absent=True,
                              cap_bytes=CARRY_MAX_BYTES)
    size = len(raw)
    if size > CARRY_MAX_BYTES:
        return False, evidence(target="proposed_carry_store", bytes=size, cap_bytes=CARRY_MAX_BYTES,
                               reason="carry_store_invalid")
    if err is not None or not isinstance(doc, dict):
        return False, evidence(target="proposed_carry_store", bytes=size, error=err,
                               reason="carry_store_invalid")
    if len(doc) > CONFIGURATION_COUNT:
        return False, evidence(target="proposed_carry_store", bytes=size, entries=len(doc),
                               configurations=CONFIGURATION_COUNT, reason="carry_store_invalid")
    return True, evidence(target="proposed_carry_store", bytes=size, cap_bytes=CARRY_MAX_BYTES,
                          entries=len(doc),
                          bytes_per_entry=round(size / max(len(doc), 1), 1))


