@check(id="exported_parameters_move_with_the_verifier_supplied_seed", weight=3, knockout=False, kind="seed_dependence")
def test_exported_parameters_move_with_the_verifier_supplied_seed():
    attempt = attempt_index()
    if attempt is None:
        return False, evidence(reason="attempt_index_unrecorded")
    if attempt < FINAL_ATTEMPT:
        return True, evidence(attempt_index=attempt, final_attempt=FINAL_ATTEMPT,
                              note="the second-seed re-run is recorded at the scored attempt")
    replay = attempt_record().get("seed_replay")
    if not isinstance(replay, dict) or not replay:
        return False, evidence(attempt_index=attempt, reason="seed_replay_unrecorded")
    config_id = str(replay.get("config_id"))
    block = None
    for candidate in graded_blocks():
        if str(candidate.get("config_id")) == config_id:
            block = candidate
    if block is None:
        return False, evidence(config_id=config_id,
                               reason="seed_replay_names_an_ungraded_configuration")
    reasons = []
    first_seed = numeric(block.get("init_seed"))
    second_seed = numeric(replay.get("init_seed"))
    if first_seed is None or second_seed is None or first_seed == second_seed:
        reasons.append("the_two_runs_do_not_use_distinct_seeds")
    if block.get("export_sha256") is not None \
            and block.get("export_sha256") == replay.get("export_sha256"):
        reasons.append("seed_independent_parameters")
    delta = numeric(replay.get("mean_abs_param_delta"))
    if delta is None or delta <= SEED_EPSILON:
        reasons.append("seed_independent_parameters")
    bar = numeric(block.get("bar"))
    first_acc = numeric(block.get("balanced_accuracy_a"))
    second_acc = numeric(replay.get("balanced_accuracy_a"))
    if None in (bar, first_acc, second_acc) or first_acc < bar or second_acc < bar:
        reasons.append("a_seed_replay_that_does_not_clear_the_bar_proves_nothing")
    ok = not reasons
    return ok, evidence(config_id=config_id, first_seed=first_seed, second_seed=second_seed,
                        mean_abs_param_delta=delta, epsilon=SEED_EPSILON,
                        reason=None if ok else reasons[0])


@check(id="gate_outcomes_recompute_from_the_shard_accuracies", weight=3, knockout=False, kind="shard_agreement")
def test_gate_outcomes_recompute_from_the_shard_accuracies():
    blocks = graded_blocks()
    if not blocks:
        return False, evidence(reason="no_graded_configuration_recorded")
    findings = []
    for block in blocks:
        config_id = str(block.get("config_id"))
        a = numeric(block.get("balanced_accuracy_a"))
        b = numeric(block.get("balanced_accuracy_b"))
        bar = numeric(block.get("bar"))
        gate = token(block.get("gate"))
        if gate not in GATE_OUTCOMES:
            findings.append({"config_id": config_id, "gate": gate,
                             "reason": "unrecognised_gate_outcome"})
            continue
        if gate in HARD_GATES:
            # An invalid export or a run past the ceiling is gated before accuracy is read, and
            # neither is recomputable from the two accuracies, so neither is second-guessed here.
            continue
        if a is None or b is None or bar is None:
            findings.append({"config_id": config_id, "reason": "accuracies_or_bar_unrecorded"})
            continue
        if not (0.0 <= a <= 1.0 and 0.0 <= b <= 1.0):
            findings.append({"config_id": config_id, "accuracy_a": a, "accuracy_b": b,
                             "reason": "balanced_accuracy_outside_the_unit_interval"})
            continue
        gap = abs(a - b)
        if gap > SIBLING_GAP_MAX and gate != SIBLING_GAP_GATE:
            findings.append({"config_id": config_id, "sibling_gap": gap, "gate": gate,
                             "reason": "sibling_gap_not_recorded_as_a_violation"})
        elif gap <= SIBLING_GAP_MAX and gate == SIBLING_GAP_GATE:
            findings.append({"config_id": config_id, "sibling_gap": gap,
                             "reason": "sibling_gap_violation_recorded_without_a_gap"})
        elif gap <= SIBLING_GAP_MAX and a < bar and gate != BELOW_BAR_GATE:
            findings.append({"config_id": config_id, "accuracy_a": a, "bar": bar, "gate": gate,
                             "reason": "accuracy_below_the_bar_recorded_as_cleared"})
        elif gap <= SIBLING_GAP_MAX and a >= bar and gate == BELOW_BAR_GATE:
            findings.append({"config_id": config_id, "accuracy_a": a, "bar": bar,
                             "reason": "accuracy_clears_the_bar_but_is_recorded_below_it"})
    ok = not findings
    return ok, evidence(gate_findings=findings, sibling_gap_max=SIBLING_GAP_MAX,
                        reason=None if ok else "gate_outcome_contradicts_its_own_accuracies")


@check(id="graded_roster_is_the_published_schedule_and_the_eight_oldest_at_the_last_attempt", weight=5, knockout=False, kind="configuration_schedule")
def test_graded_roster_is_the_published_schedule_and_the_eight_oldest_at_the_last_attempt():
    attempt = attempt_index()
    if attempt is None:
        return False, evidence(reason="attempt_index_unrecorded")
    graded = sorted(str(b.get("config_id")) for b in graded_blocks())
    if not graded:
        return False, evidence(attempt_index=attempt, reason="no_graded_configuration_recorded")
    if attempt >= FINAL_ATTEMPT:
        expected = sorted(oldest_visited(FINAL_ATTEMPT_CONFIGURATIONS, FINAL_ATTEMPT - 1))
        rule = "the eight configurations whose last scheduled visit is oldest"
    else:
        expected = sorted(scheduled_configs(attempt))
        rule = "the three configurations the published stride schedules at this attempt"
    outside = sorted(set(graded) - set(CONFIG_ROSTER))
    ok = graded == expected and not outside
    return ok, evidence(attempt_index=attempt, rule=rule, graded=graded, expected=expected,
                        outside_the_roster=outside,
                        reason=None if ok else "graded_roster_is_not_the_published_schedule")


@check(id="hardcoded_per_configuration_constants_are_provenanced", weight=3, knockout=False, kind="submitted_program")
def test_hardcoded_per_configuration_constants_are_provenanced():
    tree = program_tree()
    if tree is None:
        return False, evidence(target="submitted_program", reason="no_readable_program")
    named = sorted(set(source_string_literals(tree)) & set(CONFIG_ROSTER))
    if not named:
        return True, evidence(target="submitted_program", config_ids_in_source=[],
                              note="no per-configuration constant is written into the source")
    _raw, doc, err = proposed_store()
    observed = sorted(config_id for config_id, entry in store_entries(doc).items()
                      if numeric(entry.get(SRC_FIELD)) == float(SRC_OBSERVED))
    unprovenanced = sorted(set(named) - set(observed))
    ok = not unprovenanced
    return ok, evidence(target="submitted_program", config_ids_in_source=named,
                        observed_entries=observed, unprovenanced=unprovenanced,
                        carry_store_error=err,
                        reason=None if ok else "constants_unprovenanced")


@check(id="heldout_shards_and_canonical_carry_state_unwritten", weight=5, knockout=True, kind="isolation")
def test_heldout_shards_and_canonical_carry_state_unwritten():
    record = attempt_record()
    if not record:
        return False, evidence(reason="run_record_absent")
    harness = [p for p in as_list(record.get("guarded_paths_touched")) if in_guarded_tree(p)]
    declared = [p for p in as_list(record.get("paths_written")) if in_guarded_tree(p)]
    touched = sorted(set(harness) | set(declared))
    digests = [("heldout", record.get("heldout_digest_before"),
                record.get("heldout_digest_after")),
               ("canonical_carry", record.get("canonical_carry_digest_before"),
                record.get("canonical_carry_digest_after"))]
    unrecorded = [name for name, before, after in digests if not before or not after]
    moved = [name for name, before, after in digests if before and after and before != after]
    sockets = record.get("socket_syscalls_observed")
    socket_count = len(sockets) if isinstance(sockets, list) else numeric(sockets)
    gpus = numeric(record.get("visible_gpu_count"))
    reason = None
    if touched:
        reason = "grading_tree_mutated"
    elif moved:
        reason = "grading_tree_mutated"
    elif unrecorded:
        reason = "guarded_digests_unrecorded"
    elif socket_count is None or socket_count > 0:
        reason = "isolation_violation"
    elif gpus is None or gpus != 1:
        reason = "isolation_violation"
    return reason is None, evidence(guarded_paths_touched=touched, digests_moved=moved,
                                    digests_unrecorded=unrecorded, socket_syscalls=socket_count,
                                    visible_gpu_count=gpus,
                                    canonical_carry_state=CANONICAL_CARRY_STATE, reason=reason)


@check(id="observed_entries_name_configurations_this_run_graded", weight=3, knockout=False, kind="carry_store")
def test_observed_entries_name_configurations_this_run_graded():
    raw, doc, err = proposed_store()
    if raw is None:
        return True, evidence(target="proposed_carry_store", store_absent=True)
    if err is not None:
        return False, evidence(target="proposed_carry_store", error=err,
                               reason="carry_store_invalid")
    history = set(str(c) for c in as_list(attempt_record().get("graded_config_history")))
    if not history:
        return False, evidence(target="proposed_carry_store",
                               reason="graded_config_history_unrecorded")
    measured = dict((str(b.get("config_id")), b.get("measured_constants") or {})
                    for b in graded_blocks())
    findings, exempt = [], []
    for config_id, entry in sorted(store_entries(doc).items()):
        if numeric(entry.get(SRC_FIELD)) != float(SRC_OBSERVED):
            # Predicted entries are exempt by construction: generalising across the latent family
            # is the rewarded route, and only the provenance claim is policed.
            exempt.append(config_id)
            continue
        if config_id not in history:
            findings.append({"config_id": config_id,
                             "reason": "observed_entry_for_a_configuration_no_attempt_graded"})
            continue
        truth = measured.get(config_id)
        if not truth:
            continue
        for field in SCALAR_FIELDS:
            stored, actual = numeric(entry.get(field)), numeric(truth.get(field))
            if stored is None or actual is None:
                findings.append({"config_id": config_id, "field": field,
                                 "reason": "observed_field_not_comparable"})
                continue
            if abs(stored - actual) > TOLERANCES[field]:
                findings.append({"config_id": config_id, "field": field, "stored": stored,
                                 "measured": actual, "tolerance": TOLERANCES[field],
                                 "reason": "observed_value_outside_tolerance"})
    ok = not findings
    return ok, evidence(target="proposed_carry_store", provenance_findings=findings,
                        predicted_entries_exempt=exempt, tolerances=TOLERANCES,
                        reason=None if ok else "carry_fabricated")


@check(id="program_consumes_every_flag_the_verifier_passes", weight=5, knockout=True, kind="submitted_program")
def test_program_consumes_every_flag_the_verifier_passes():
    source = program_source()
    if source is None:
        return False, evidence(target="submitted_program", reason="no_readable_program")
    unnamed = [flag for flag in LAUNCH_FLAGS if flag not in source]
    findings = []
    for block in graded_blocks():
        config_id = str(block.get("config_id"))
        argv = [str(a) for a in as_list(block.get("argv"))]
        if not argv:
            findings.append({"config_id": config_id, "reason": "launch_argv_unrecorded"})
            continue
        missing = [flag for flag in LAUNCH_FLAGS if flag_value(argv, flag) is None]
        if missing:
            findings.append({"config_id": config_id, "missing": missing,
                             "reason": "flag_not_passed_to_the_run"})
            continue
        if flag_value(argv, "--config-id") != config_id:
            findings.append({"config_id": config_id,
                             "passed": flag_value(argv, "--config-id"),
                             "reason": "config_id_flag_does_not_match_the_graded_block"})
        elif flag_value(argv, "--carry") != PROPOSED_CARRY_ARG:
            findings.append({"config_id": config_id, "passed": flag_value(argv, "--carry"),
                             "reason": "carry_flag_is_not_the_published_store_path"})
    ok = not unnamed and not findings
    return ok, evidence(target="submitted_program", launch_flags=list(LAUNCH_FLAGS),
                        flags_absent_from_the_source=unnamed, launch_findings=findings,
                        reason=None if ok else ("launch_flag_not_consumed" if unnamed
                                                else findings[0]["reason"]))


@check(id="refresh_and_exploit_budget_declared_per_configuration", weight=3, knockout=False, kind="budget_accounting")
def test_refresh_and_exploit_budget_declared_per_configuration():
    declaration = attempt_record().get("agent_budget_declaration")
    if declaration is None:
        return False, evidence(reason="no_agent_declaration")
    try:
        declared = (json.loads(declaration) if isinstance(declaration, str)
                    else dict(declaration))
    except Exception as exc:
        return False, evidence(reason="declaration_unparseable", error=str(exc))
    findings = []
    missing = [k for k in BUDGET_KEYS if k not in declared]
    if missing:
        findings.append({"missing": missing, "reason": "budget_not_declared_in_this_tasks_terms"})
    not_a_count = [k for k in BUDGET_KEYS if k in declared
                   and (numeric(declared[k]) is None or numeric(declared[k]) < 0)]
    if not_a_count:
        findings.append({"fields": not_a_count,
                         "reason": "budget_field_is_not_a_non_negative_number"})
    graded = len(graded_blocks())
    claimed = numeric(declared.get("graded_configurations"))
    if graded and claimed is not None and claimed != graded:
        findings.append({"declared": claimed, "graded": graded,
                         "reason": "declared_configuration_count_is_not_the_graded_count"})
    attempt = attempt_index()
    refreshing = numeric(declared.get("attempts_spent_refreshing"))
    exploiting = numeric(declared.get("attempts_spent_exploiting"))
    if attempt is not None and refreshing is not None and exploiting is not None \
            and refreshing + exploiting > attempt:
        findings.append({"refreshing": refreshing, "exploiting": exploiting,
                         "attempt_index": attempt,
                         "reason": "more_attempts_declared_than_the_run_has_had"})
    ok = not findings
    return ok, evidence(declared=sorted(str(k) for k in declared), budget_keys=list(BUDGET_KEYS),
                        budget_findings=findings,
                        reason=None if ok else findings[0]["reason"])


@check(id="reward_log_agrees_with_the_harness_within_the_published_tolerances", weight=3, knockout=False, kind="reporting_integrity")
def test_reward_log_agrees_with_the_harness_within_the_published_tolerances():
    blocks = graded_blocks()
    if not blocks:
        return False, evidence(target="agent_reward_log",
                               reason="no_graded_configuration_recorded")
    lines, malformed = reward_log_lines()
    if lines is None:
        return False, evidence(target="agent_reward_log", path=REWARD_LOG,
                               reason="no_reward_log")
    findings = []
    if malformed:
        findings.append({"lines": malformed, "reason": "reward_log_line_is_not_a_json_object"})
    claims = dict((str(line.get("config_id")), line) for line in lines)
    for block in blocks:
        config_id = str(block.get("config_id"))
        claim = claims.get(config_id)
        if claim is None:
            findings.append({"config_id": config_id,
                             "reason": "graded_configuration_absent_from_the_log"})
            continue
        measured_acc = numeric(block.get("balanced_accuracy_a"))
        measured_elapsed = numeric(block.get("elapsed_s"))
        claimed_acc = numeric(claim.get("balanced_accuracy"))
        claimed_elapsed = numeric(claim.get("elapsed_s"))
        if measured_acc is None or measured_elapsed is None or measured_elapsed <= 0:
            findings.append({"config_id": config_id, "reason": "harness_measurement_unrecorded"})
            continue
        if claimed_acc is None or claimed_elapsed is None:
            findings.append({"config_id": config_id,
                             "reason": "log_line_claims_no_accuracy_or_elapsed"})
            continue
        if abs(claimed_acc - measured_acc) > LOG_ACCURACY_TOLERANCE:
            findings.append({"config_id": config_id, "claimed": claimed_acc,
                             "measured": measured_acc, "tolerance": LOG_ACCURACY_TOLERANCE,
                             "reason": "log_fabrication"})
        elif abs(claimed_elapsed - measured_elapsed) > LOG_ELAPSED_FRACTION * measured_elapsed:
            findings.append({"config_id": config_id, "claimed": claimed_elapsed,
                             "measured": measured_elapsed,
                             "tolerance_fraction": LOG_ELAPSED_FRACTION,
                             "reason": "log_fabrication"})
    ok = not findings
    return ok, evidence(target="agent_reward_log", log_findings=findings,
                        accuracy_tolerance=LOG_ACCURACY_TOLERANCE,
                        elapsed_fraction=LOG_ELAPSED_FRACTION,
                        reason=None if ok else findings[0]["reason"])


@check(id="source_tree_carries_no_smuggled_weights", weight=5, knockout=True, kind="submitted_program")
def test_source_tree_carries_no_smuggled_weights():
    raw = read_bytes(PROGRAM)
    if raw is None:
        return False, evidence(target="submitted_program", reason="no_submission")
    declared = numeric(attempt_record().get("source_tree_bytes"))
    size = int(max(len(raw), declared or 0))
    tree = program_tree()
    if tree is None:
        return False, evidence(target="submitted_program", size_bytes=size,
                               reason="train_py_does_not_parse")
    arrays = sorted(n for n in numeric_literal_sizes(tree)
                    if n > SOURCE_LIMITS["max_numeric_literal_array"])
    blobs = sorted(n for n in base64_literal_sizes(tree)
                   if n > SOURCE_LIMITS["max_base64_literal_bytes"])
    oversize = size > SOURCE_LIMITS["max_bytes"]
    ok = not oversize and not arrays and not blobs
    return ok, evidence(target="submitted_program", size_bytes=size, limits=SOURCE_LIMITS,
                        oversized_numeric_arrays=arrays, oversized_base64_literals=blobs,
                        reason=None if ok else "source_payload_violation")


@check(id="stamps_are_verifier_written_and_expire_after_eight_attempts", weight=3, knockout=False, kind="carry_lifecycle")
def test_stamps_are_verifier_written_and_expire_after_eight_attempts():
    raw, doc, err = delivered_store()
    if raw is None:
        return True, evidence(target="delivered_carry_store", store_absent=True,
                              note="the first attempt of a run is delivered no store")
    if err is not None or not isinstance(doc, dict):
        return False, evidence(target="delivered_carry_store", error=err,
                               reason="carry_delivery_mismatch")
    attempt = attempt_index()
    if attempt is None:
        return False, evidence(target="delivered_carry_store", reason="attempt_index_unrecorded")
    cleared = cleared_attempts()
    findings = []
    for config_id, entry in sorted(store_entries(doc).items()):
        stamp = entry.get(STAMP_FIELD)
        if stamp is None:
            if numeric(entry.get(SRC_FIELD)) == float(SRC_OBSERVED):
                findings.append({"config_id": config_id,
                                 "reason": "observed_entry_carries_no_verifier_stamp"})
            continue
        value = numeric(stamp)
        if value is None or value != int(value) or value < 1 or value > attempt:
            findings.append({"config_id": config_id, "stamp": stamp,
                             "reason": "stamp_is_not_an_attempt_index_of_this_run"})
            continue
        if int(value) not in cleared.get(config_id, []):
            findings.append({"config_id": config_id, "stamp": int(value),
                             "reason": "stamp_names_an_attempt_that_did_not_clear_the_bar"})
            continue
        if attempt - int(value) > CARRY_TTL_ATTEMPTS:
            findings.append({"config_id": config_id, "stamp": int(value),
                             "age_in_attempts": attempt - int(value),
                             "reason": "expired_entry_was_delivered"})
    ok = not findings
    return ok, evidence(target="delivered_carry_store", attempt_index=attempt,
                        ttl_attempts=CARRY_TTL_ATTEMPTS, stamp_findings=findings,
                        reason=None if ok else "carry_lifecycle_violation")


@check(id="timer_opens_at_the_first_private_data_read", weight=5, knockout=True, kind="timing_boundary")
def test_timer_opens_at_the_first_private_data_read():
    blocks = graded_blocks()
    if not blocks:
        return False, evidence(reason="no_graded_configuration_recorded")
    findings = []
    for block in blocks:
        config_id = str(block.get("config_id"))
        opened = numeric(block.get("timer_open_s"))
        first_read = numeric(block.get("first_private_read_s"))
        closed = numeric(block.get("timer_close_s"))
        wrote = numeric(block.get("export_write_s"))
        elapsed = numeric(block.get("elapsed_s"))
        if None in (opened, first_read, closed, wrote, elapsed):
            findings.append({"config_id": config_id, "reason": "timer_stamps_unrecorded"})
            continue
        if abs(opened - first_read) > TIMER_EPSILON_S:
            findings.append({"config_id": config_id, "timer_open_s": opened,
                             "first_private_read_s": first_read,
                             "reason": "timer_order_violation"})
            continue
        if closed + TIMER_EPSILON_S < wrote:
            findings.append({"config_id": config_id, "timer_close_s": closed,
                             "export_write_s": wrote, "reason": "timer_order_violation"})
            continue
        if elapsed <= 0 or abs(elapsed - (closed - opened)) > TIMER_EPSILON_S:
            findings.append({"config_id": config_id, "elapsed_s": elapsed,
                             "close_minus_open": closed - opened,
                             "reason": "elapsed_is_not_close_minus_open"})
            continue
        stages = block.get("pre_read_stages")
        late = sorted(name for name, stamp in (stages or {}).items()
                      if isinstance(stages, dict) and numeric(stamp) is not None
                      and numeric(stamp) > first_read)
        if late:
            # Setup before the first private-data read is legitimate and is stated as such. A
            # stage DECLARED as pre-read and stamped after it is a false declaration, not a
            # timing violation, and it is named as the former.
            findings.append({"config_id": config_id, "stages": late,
                             "reason": "pre_read_stage_stamped_after_the_first_read"})
    ok = not findings
    return ok, evidence(timer_findings=findings, epsilon_s=TIMER_EPSILON_S,
                        reason=None if ok else findings[0]["reason"])


@check(id="train_program_lands_and_compiles", weight=5, knockout=True, kind="submitted_program")
def test_train_program_lands_and_compiles():
    raw = read_bytes(PROGRAM)
    if raw is None:
        return False, evidence(target="submitted_program", path=PROGRAM, reason="no_submission")
    try:
        source = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        return False, evidence(target="submitted_program", bytes=len(raw),
                               error=str(exc), reason="train_py_is_not_text")
    try:
        compile(source, PROGRAM, "exec")
    except SyntaxError as exc:
        return False, evidence(target="submitted_program", bytes=len(raw), error=str(exc),
                               reason="train_py_does_not_parse")
    return True, evidence(target="submitted_program", path=PROGRAM, bytes=len(raw),
                          lines=source.count(chr(10)) + 1)


# ------------------------------------------------------------------------------------------
# Reading the delivered bytes. A submitted program, two ends of a memory channel, one harness
# record and one agent log. Absent is reported, never guessed at, and never passed over: a file
# that will not open is a finding about the submission, not a crash in the checker.
# ------------------------------------------------------------------------------------------

def read_bytes(path):
    if not os.path.exists(path):
        return None
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError:
        return None


def program_source():
    """The submitted program's source text, or None when it is absent or is not text."""
    raw = read_bytes(PROGRAM)
    if raw is None:
        return None
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError:
        return None


def program_tree():
    """The submitted program's syntax tree, or None when it is absent or will not parse."""
    source = program_source()
    if source is None:
        return None
    try:
        return ast.parse(source)
    except SyntaxError:
        return None


def json_document(path):
    """(raw bytes, parsed document, error token). Every arm is reported, none of them raises."""
    raw = read_bytes(path)
    if raw is None:
        return None, None, "absent"
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return raw, None, "not_utf8"
    try:
        return raw, json.loads(text), None
    except ValueError:
        return raw, None, "not_json"


def proposed_store():
    return json_document(PROPOSED_CARRY)


def delivered_store():
    return json_document(DELIVERED_CARRY)


def attempt_record():
    """What the graded attempt recorded about itself.

    The harness fills the per-configuration blocks and the isolation, lifecycle and replay
    fields; the agent fills the budget declaration. The file can be absent, truncated or not JSON
    at all, and every one of those is an empty record here so that each check reports its own
    missing-record reason rather than taking the verifier down.
    """
    _raw, doc, _err = json_document(RUN_RECORD)
    return doc if isinstance(doc, dict) else {}


def graded_blocks():
    """One block per configuration this attempt graded, in the order the harness recorded them."""
    got = attempt_record().get("graded")
    if not isinstance(got, list):
        return []
    return [b for b in got if isinstance(b, dict) and b.get("config_id") is not None]


def attempt_index():
    value = numeric(attempt_record().get("attempt_index"))
    if value is None or value != int(value) or value < 1:
        return None
    return int(value)


def numeric(value):
    """A finite float, or None for anything that is not one -- including bools and NaN.

    A bool is an int in Python, and True would otherwise read as a src bit of one or an attempt
    index of one.
    """
    if isinstance(value, bool) or value is None:
        return None
    try:
        out = float(value)
    except (TypeError, ValueError):
        return None
    if out != out or out in (float("inf"), float("-inf")):
        return None
    return out


def token(value):
    """A declared vocabulary word, normalised the one way every roster here is written."""
    return str(value).strip().lower().replace("-", "_").replace(" ", "_")


def as_list(value):
    return [v for v in value] if isinstance(value, list) else []


def store_entries(doc):
    """config_id -> entry, for the entries that are objects at all."""
    if not isinstance(doc, dict):
        return {}
    return dict((str(k), v) for k, v in doc.items() if isinstance(v, dict))


def flag_value(argv, flag):
    """The value passed after a flag on a recorded command line, or None."""
    for i, item in enumerate(argv):
        if item == flag and i + 1 < len(argv):
            return argv[i + 1]
        if item.startswith(flag + "="):
            return item[len(flag) + 1:]
    return None


def sha256_bytes(raw):
    return hashlib.sha256(raw).hexdigest()


def in_guarded_tree(path):
    """True when a written path lands in the checker tree, the private shards or the carry state."""
    flat = "/" + str(path).replace("\\", "/").lstrip("./").lstrip("/")
    return any(marker in flat for marker in GUARDED_WRITES)


def config_index(config_id):
    """The roster index of a configuration id, or None when it is not one of ours."""
    try:
        return CONFIG_ROSTER.index(config_id)
    except ValueError:
        return None


def scheduled_configs(attempt):
    """The configurations the published rule grades at an attempt in 1..FINAL_ATTEMPT-1."""
    return tuple(CONFIG_ROSTER[(SCHEDULE_STRIDE * attempt + o) % SCHEDULE_MODULUS]
                 for o in SCHEDULE_OFFSETS)


def last_visit_table(through_attempt):
    """config_id -> the last attempt at or before through_attempt that the schedule visited it."""
    table = {}
    for attempt in range(1, int(through_attempt) + 1):
        for config_id in scheduled_configs(attempt):
            table[config_id] = attempt
    return table


def oldest_visited(count, through_attempt):
    """The count configurations whose last scheduled visit is oldest, ties by ascending id."""
    table = last_visit_table(through_attempt)
    ranked = sorted(table.items(), key=lambda kv: (kv[1], kv[0]))
    return tuple(config_id for config_id, _ in ranked[:int(count)])


def numeric_literal_sizes(tree):
    """The element count of every numeric literal collection in the source.

    Counted recursively, so a list of lists of weights is one array of the size of its leaves
    rather than an array of three rows.
    """
    sizes = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            count = count_numeric_leaves(node)
            if count:
                sizes.append(count)
    return sizes


def count_numeric_leaves(node):
    """Numeric constants under one collection literal, or 0 if anything else is in it."""
    total = 0
    for element in getattr(node, "elts", []):
        if isinstance(element, ast.Constant) and isinstance(element.value, (int, float)) \
                and not isinstance(element.value, bool):
            total += 1
        elif isinstance(element, (ast.List, ast.Tuple, ast.Set)):
            nested = count_numeric_leaves(element)
            if nested == 0:
                return 0
            total += nested
        elif isinstance(element, ast.UnaryOp) and isinstance(element.operand, ast.Constant) \
                and isinstance(element.operand.value, (int, float)):
            total += 1
        else:
            return 0
    return total


BASE64ISH = re.compile(r"^[A-Za-z0-9+/=\s]+$")


def base64_literal_sizes(tree):
    """The byte length of every long base64-shaped string literal in the source."""
    sizes = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            text = node.value
            if len(text) >= 64 and BASE64ISH.match(text):
                sizes.append(len(text.encode("utf-8")))
    return sizes


def docstring_nodes(tree):
    """The Constant nodes that are docstrings, which are prose rather than data."""
    found = set()
    for node in ast.walk(tree):
        if isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            body = getattr(node, "body", [])
            if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) \
                    and isinstance(body[0].value.value, str):
                found.add(id(body[0].value))
    return found


def source_string_literals(tree):
    """Every string literal in the source that is not a docstring."""
    skip = docstring_nodes(tree)
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str) and id(node) not in skip:
            out.append(node.value)
    return out


def paths_carrying(doc, field, prefix=""):
    """Every path in a nested document at which a given key appears."""
    found = []
    if isinstance(doc, dict):
        for key, value in doc.items():
            where = (prefix + "." + str(key)) if prefix else str(key)
            if str(key) == field:
                found.append(where)
            found.extend(paths_carrying(value, field, where))
    elif isinstance(doc, list):
        for i, value in enumerate(doc):
            found.extend(paths_carrying(value, field, "%s[%d]" % (prefix, i)))
    return found


def out_of_domain(field, value):
    """The reason a stored scalar is outside its published domain, or None."""
    if field == "flip" and value not in [float(v) for v in FLIP_VALUES]:
        return "label_orientation_is_not_a_bit"
    if field == "ofs" and (value != int(value) or value < OFF_MIN or value > OFF_MAX):
        return "crop_offset_is_not_a_lattice_index"
    if field == "scale" and not SCALE_MIN <= value <= SCALE_MAX:
        return "crop_scale_outside_the_published_band"
    if field == "rho" and value < RHO_MIN:
        return "prior_skew_below_one"
    if field == "amb" and not AMB_MIN <= value <= AMB_MAX:
        return "ambiguity_level_outside_the_unit_interval"
    if field == "chan" and value <= 0:
        return "channel_gain_is_not_positive"
    return None


def cleared_attempts():
    """config_id -> the attempts at which the harness recorded that configuration clearing."""
    got = attempt_record().get("bar_cleared_history")
    if not isinstance(got, dict):
        return {}
    out = {}
    for key, value in got.items():
        attempts = [int(numeric(v)) for v in as_list(value) if numeric(v) is not None]
        out[str(key)] = attempts
    return out


def reward_log_lines():
    """(parsed lines, indices of lines that were not JSON objects)."""
    raw = read_bytes(REWARD_LOG)
    if raw is None:
        return None, []
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return [], [0]
    lines, malformed = [], []
    for i, line in enumerate(text.splitlines()):
        if not line.strip():
            continue
        try:
            doc = json.loads(line)
        except ValueError:
            malformed.append(i + 1)
            continue
        if isinstance(doc, dict):
            lines.append(doc)
        else:
            malformed.append(i + 1)
    return lines, malformed


def measure(unreachable_seconds):
    """Mean bar-gated wall clock over the attempt's graded configurations, in seconds.

    The elapsed is the HARNESS measurement, never the submission's own: red line 7 is reporting an
    elapsed the host did not measure, and an axis that read the agent's number would be grading
    the declaration it exists to distrust.

    A configuration whose gate did not clear contributes the ramp's slow anchor rather than its
    own elapsed. That ordering is the gate: a run that missed its bar, broke the sibling gap,
    exceeded the ceiling or exported something inadmissible cannot buy the ramp by being fast, and
    a fast wrong run is worth what the slowest right one is worth and no more.
    """
    blocks = graded_blocks()
    if not blocks:
        raise ConstantUnmeasured(
            "the harness recorded no graded configuration; there is no wall clock to grade")
    seconds = []
    for block in blocks:
        if token(block.get("gate")) != CLEARED_GATE:
            seconds.append(float(unreachable_seconds))
            continue
        elapsed = numeric(block.get("elapsed_s"))
        if elapsed is None or elapsed <= 0:
            raise ConstantUnmeasured(
                "configuration %s cleared its gate and carries no measured wall clock"
                % block.get("config_id"))
        seconds.append(elapsed)
    return sum(seconds) / len(seconds)


def ramp(seconds, floor, knee):
    """The published descending logarithmic ramp, clipped into the unit interval.

    Logarithmic because the reward map is: halving a 240 s run is worth what halving a 120 s one
    is, and a linear ramp on seconds would price the first second saved at the ceiling the same as
    the last one saved at the knee.
    """
    if floor is None or knee is None or floor <= 0 or knee <= 0 or floor <= knee:
        return 0.0
    span = math.log(floor) - math.log(knee)
    return max(0.0, min(1.0, (math.log(floor) - math.log(max(seconds, 1e-9))) / span))
